update public.questions set body_hi = 'बकाया राजस्व की वसूली के लिए बनाया गया विभाग ''दीवान-ए-मुस्तखराज'' किस दिल्ली सुल्तान ने स्थापित किया?', explanation_hi = 'अलाउद्दीन खिलजी ने बकाया राजस्व वसूलने के लिए दीवान-ए-मुस्तखराज बनाया। बाकी विभागों को प्रायः इससे मिला दिया जाता है: दीवान-ए-अमीर-कोही (कृषि) मुहम्मद बिन तुगलक ने, दीवान-ए-खैरात (दान) और दीवान-ए-बंदगान (गुलाम) फ़िरोज़ शाह तुगलक ने बनाए, और बलबन सैन्य विभाग दीवान-ए-अर्ज़ के पुनर्गठन से जुड़ा है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "बलबन", "b": "मुहम्मद बिन तुगलक", "c": "फ़िरोज़ शाह तुगलक", "d": "अलाउद्दीन खिलजी"}'::jsonb as hi) h) where id = 'f2ae949b-376c-4d4d-b4fc-2d8c21d1bd29' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'साइमन आयोग के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 सही है: नवंबर 1927 में नियुक्त साइमन आयोग (औपचारिक रूप से भारतीय वैधानिक आयोग) को मॉन्टेग्यू-चेम्सफ़ोर्ड सुधारों (भारत शासन अधिनियम, 1919) के कामकाज की समीक्षा और आगे के संवैधानिक सुधारों की सिफ़ारिश का काम सौंपा गया था। कथन 2 सही है: सर जॉन साइमन की अध्यक्षता वाले आयोग के सभी सदस्य ब्रिटिश थे और कोई भारतीय सदस्य नहीं था, इसीलिए 1928 में इसके आने पर पूरे भारत में ''साइमन वापस जाओ'' के नारे के साथ इसका बहिष्कार हुआ।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसका गठन भारत शासन अधिनियम, 1919 के कामकाज की समीक्षा करने और आगे के संवैधानिक सुधारों की सिफ़ारिश करने के लिए हुआ था।", "इसमें एक भी भारतीय सदस्य नहीं था।"]}'::jsonb where id = '4772b5c6-bfc0-4094-b0ce-906326a3a1b5' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'पूना समझौते (1932) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 सही है: पूना समझौता (24 सितंबर 1932) दलित वर्गों के पृथक निर्वाचन के विरुद्ध यरवदा केंद्रीय जेल में अनशन कर रहे महात्मा गांधी और दलित वर्गों का प्रतिनिधित्व कर रहे डॉ. बी.आर. आंबेडकर के बीच हुआ। कथन 2 गलत है: समझौते ने आरक्षण समाप्त नहीं किया; इसने सांप्रदायिक पंचाट की दलित वर्गों के लिए पृथक निर्वाचन की व्यवस्था की जगह एक संयुक्त निर्वाचन के भीतर आरक्षित सीटें रखीं, और आरक्षण बना रहा। कथन 3 सही है: पृथक निर्वाचन छोड़ने की भरपाई के लिए समझौते ने प्रांतीय विधानमंडलों में आरक्षित सीटों की संख्या सांप्रदायिक पंचाट में प्रस्तावित संख्या से बढ़ा दी।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह महात्मा गांधी और डॉ. बी.आर. आंबेडकर के बीच हुआ।", "इसने प्रांतीय विधानमंडलों में दलित वर्गों के लिए सीटों का आरक्षण समाप्त कर दिया।", "इस समझौते के तहत प्रांतीय विधानमंडलों में दलित वर्गों के लिए आरक्षित सीटों की संख्या सांप्रदायिक पंचाट में प्रस्तावित संख्या से अधिक थी।"]}'::jsonb where id = '6e764bab-74e4-4b64-b1a1-e7c6e036a87b' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'भारतीय परिषद अधिनियम, 1909 (मॉर्ले-मिंटो सुधार), जिसने पहली बार मुसलमानों के लिए पृथक निर्वाचन शुरू किया, निम्नलिखित में से किसके वायसराय काल में पारित हुआ?', explanation_hi = 'भारतीय परिषद अधिनियम, 1909, जिसे भारत मंत्री जॉन मॉर्ले और वायसराय लॉर्ड मिंटो द्वितीय के नाम पर मॉर्ले-मिंटो सुधार कहते हैं, लॉर्ड मिंटो के वायसराय काल (1905-1910) में पारित हुआ; इसने विधान परिषदों का विस्तार किया और पहली बार मुसलमानों के लिए पृथक निर्वाचन शुरू किया। लॉर्ड कर्ज़न (1899-1905) मिंटो से पहले थे और 1905 के बंगाल विभाजन से जुड़े हैं। लॉर्ड हार्डिंग (1910-1916) उनके बाद आए और राजधानी के दिल्ली स्थानांतरण (1911) तथा ग़दर आंदोलन से जुड़े हैं। लॉर्ड चेम्सफ़ोर्ड (1916-1921) मॉन्टेग्यू-चेम्सफ़ोर्ड सुधारों (1919) और जलियाँवाला बाग हत्याकांड (1919) से जुड़े हैं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "लॉर्ड मिंटो", "b": "लॉर्ड कर्ज़न", "c": "लॉर्ड हार्डिंग", "d": "लॉर्ड चेम्सफ़ोर्ड"}'::jsonb as hi) h) where id = '6f46e193-9f72-450e-a3fe-294118d62920' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'भारत शासन अधिनियम, 1935 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। कथन 1 गलत है: अधिनियम ने एकात्मक राज्य के बजाय प्रांतों और रियासतों के एक अखिल भारतीय संघ का प्रस्ताव रखा। कथन 2 गलत है: प्रांतों में द्वैध शासन 1919 के अधिनियम ने शुरू किया था; 1935 के अधिनियम ने इसे वहाँ समाप्त किया (और केंद्र में शुरू किया) तथा प्रांतीय स्वायत्तता दी। कथन 3 गलत है: पर्याप्त रियासतों के शामिल न होने के कारण संघ कभी लागू नहीं हुआ; केवल प्रांतीय स्वायत्तता 1937 में लागू हुई।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसने संघ का विचार छोड़ दिया और उसकी जगह एकात्मक राज्य का प्रावधान किया।", "इसने पहली बार प्रांतों में द्वैध शासन (dyarchy) शुरू किया।", "प्रस्तावित अखिल भारतीय संघ 1937 में प्रांतीय स्वायत्तता के साथ वास्तव में लागू हो गया।"]}'::jsonb where id = '3b901c20-f883-4013-ab46-2fdab3c2dcf7' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'सविनय अवज्ञा आंदोलन और दांडी यात्रा (1930) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 2 सही है: यात्रा ने 12 मार्च से 6 अप्रैल 1930 तक, 24 दिनों में, लगभग 240 मील की दूरी तय की। कथन 1 गलत है: गांधीजी ने यात्रा साबरमती आश्रम से शुरू की, सेवाग्राम (वर्धा का वह आश्रम जहाँ वे बाद में बसे) से नहीं। कथन 3 दोनों बातों में गलत है: आंदोलन 1932 के पूना समझौते के बाद नहीं, 1931 के गांधी-इरविन समझौते के बाद स्थगित हुआ, और गांधीजी फिर पहले नहीं, दूसरे गोलमेज़ सम्मेलन में गए।', updated_at = now(), question_data = question_data || '{"statements_hi": ["महात्मा गांधी ने दांडी यात्रा वर्धा के सेवाग्राम आश्रम से शुरू की।", "यात्रा ने 24 दिनों में लगभग 240 मील की दूरी तय की।", "1932 के पूना समझौते के बाद आंदोलन औपचारिक रूप से स्थगित कर दिया गया, जिसके बाद कांग्रेस ने पहले गोलमेज़ सम्मेलन में भाग लिया।"]}'::jsonb where id = 'd3234b03-8660-4123-b402-9a8e84c1543d' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'सहमति आयु अधिनियम (1891) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। अधिनियम ने सहमति की आयु 10 से बढ़ाकर 12 वर्ष की। यह 1890 में बाल-वधू फूलमनी की मृत्यु पर हुए जन-आक्रोश के बाद आया। तिलक सहित रूढ़िवादी हिंदू मत के कुछ वर्गों ने इसे सामाजिक और धार्मिक रीति-रिवाजों में अनुचित हस्तक्षेप मानकर इसका विरोध किया; इस मुद्दे पर यह रुख उन्हें अपने सुधारवादी समकालीनों के विरुद्ध खड़ा करता था।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसने विवाह में सहवास के लिए लड़कियों की सहमति की आयु 10 से बढ़ाकर 12 वर्ष कर दी।", "यह एक बाल-वधू फूलमनी की मृत्यु पर हुए जन-आक्रोश के बाद बनाया गया।", "रूढ़िवादी हिंदू समाज के कुछ वर्गों ने, जिनमें बाल गंगाधर तिलक भी थे, इसे धार्मिक और सामाजिक रीति-रिवाजों में हस्तक्षेप मानकर इसका विरोध किया।"]}'::jsonb where id = '0f91f53f-0ea7-4c30-9004-79e0430ccf34' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'देशी भाषा समाचार-पत्र अधिनियम (1878) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। कथन 1 गलत वायसराय का नाम देता है: अधिनियम लॉर्ड लिटन के समय (1878) पारित हुआ, और लॉर्ड रिपन ने 1882 में इसे निरस्त किया। कथन 2 इसकी कठोरता को उलट देता है: अधिनियम ने बिना अपील के अधिकार के प्रेस सामग्री ज़ब्त करने की अनुमति दी। कथन 3 गलत है: यह केवल देशी भाषाओं के समाचार-पत्रों पर लागू था, अंग्रेज़ी समाचार-पत्रों को इससे छूट थी।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह लॉर्ड रिपन के वायसराय काल में बनाया गया।", "इसने सरकार को प्रेस सामग्री केवल न्यायालय में मुकदमे के बाद, अपील के अधिकार के साथ, ज़ब्त करने का अधिकार दिया।", "यह देशी भाषा और अंग्रेज़ी भाषा, दोनों के समाचार-पत्रों पर समान रूप से लागू था।"]}'::jsonb where id = 'd02651cd-4682-480c-bc3d-65df59df138a' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'अक्टूबर 1940 में महात्मा गांधी द्वारा शुरू किए गए व्यक्तिगत सत्याग्रह में पहले व्यक्तिगत सत्याग्रही के रूप में किसे चुना गया?', explanation_hi = 'गांधीजी ने अक्टूबर 1940 में विनोबा भावे को पहला व्यक्तिगत सत्याग्रही चुना, जिन्होंने जन-आंदोलन के बजाय व्यक्तिगत आधार पर युद्ध-विरोधी सांकेतिक प्रतिरोध किया। जवाहरलाल नेहरू इस क्रम में दूसरे सत्याग्रही चुने गए, पहले नहीं; यह विवरण प्रायः भ्रम पैदा करता है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "जवाहरलाल नेहरू", "b": "विनोबा भावे", "c": "राजेंद्र प्रसाद", "d": "सरदार वल्लभभाई पटेल"}'::jsonb as hi) h) where id = 'bc383154-7368-4a74-88dc-ca7ca66caf2e' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'महात्मा गांधी का भारत में पहला सत्याग्रह, चंपारण सत्याग्रह (1917), किसानों पर थोपी गई नील की जबरन खेती की किस व्यवस्था के विरुद्ध था?', explanation_hi = 'तिनकठिया व्यवस्था चंपारण के किसानों को अपनी भूमि के 3/20 भाग (लगभग प्रति बीघा 3 कट्ठा) पर यूरोपीय बागान मालिकों के लिए, उनके तय किए दामों पर, नील उगाने के लिए बाध्य करती थी। इन शिकायतों पर गांधीजी की 1917 की जाँच भारत की धरती पर उनका पहला सत्याग्रह था। स्थायी बंदोबस्त, रैयतवाड़ी और महालवाड़ी व्यवस्थाएँ औपनिवेशिक भू-राजस्व व्यवस्थाएँ हैं, खेती के आदेश नहीं, और चंपारण की शिकायत से इनका संबंध नहीं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "तिनकठिया व्यवस्था", "b": "स्थायी बंदोबस्त", "c": "रैयतवाड़ी व्यवस्था", "d": "महालवाड़ी व्यवस्था"}'::jsonb as hi) h) where id = 'b50ade26-5bf3-4bd8-9cde-f4c4f8d05366' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'महात्मा गांधी ने असहयोग आंदोलन (1920-22) किस घटना के तुरंत बाद वापस लिया?', explanation_hi = 'फ़रवरी 1922 में चौरी चौरा (संयुक्त प्रांत) में एक हिंसक भीड़ द्वारा 22 पुलिसकर्मियों की हत्या के बाद गांधीजी ने असहयोग आंदोलन वापस ले लिया, क्योंकि उन्हें लगा कि इससे आंदोलन की अहिंसा की प्रतिबद्धता टूटी है। जलियाँवाला बाग हत्याकांड (1919) आंदोलन से पहले हुआ और उसे भड़काने में सहायक बना; मोपला विद्रोह (1921) मालाबार का एक अलग, सांप्रदायिक रंग लिए विद्रोह था; काकोरी कांड (1925) बाद की एक क्रांतिकारी कार्रवाई थी।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "जलियाँवाला बाग हत्याकांड", "b": "चौरी चौरा की घटना", "c": "मोपला विद्रोह", "d": "काकोरी कांड"}'::jsonb as hi) h) where id = 'd50264bf-02f2-48f7-985d-5e26f53d0ac0' and exam_category = 'upsc' returning id;
update public.questions set body_hi = '1906 में ढाका में स्थापित अखिल भारतीय मुस्लिम लीग के पहले अध्यक्ष किसे बनाया गया?', explanation_hi = 'दिसंबर 1906 में ढाका में स्थापना के समय आगा ख़ान तृतीय अखिल भारतीय मुस्लिम लीग के पहले अध्यक्ष चुने गए। नवाब सलीमुल्लाह ख़ान ने स्थापना बैठक की मेज़बानी की और इसके प्रमुख आयोजक थे, पर पहले अध्यक्ष नहीं थे। जिन्ना वर्षों बाद लीग में शामिल हुए और उसका नेतृत्व किया। अलीगढ़ आंदोलन से जुड़े सैयद अहमद ख़ान की मृत्यु लीग बनने से पहले 1898 में हो चुकी थी।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "मुहम्मद अली जिन्ना", "b": "नवाब सलीमुल्लाह ख़ान", "c": "आगा ख़ान तृतीय", "d": "सैयद अहमद ख़ान"}'::jsonb as hi) h) where id = '735a2e7c-77bc-4956-8794-70aedb75e16e' and exam_category = 'upsc' returning id;
update public.questions set body_hi = '1905 में घोषित लॉर्ड कर्ज़न के बंगाल विभाजन को औपनिवेशिक सरकार ने किस वर्ष रद्द किया?', explanation_hi = 'स्वदेशी काल के लगातार आंदोलन के बाद 1911 में दिल्ली दरबार में घोषणा करके बंगाल विभाजन रद्द किया गया। 1908 आंदोलन के बीच का वर्ष है, रद्द होने का नहीं; 1919 और 1935 बाद के असंबंधित संवैधानिक सुधारों (भारत शासन अधिनियमों) से जुड़े हैं।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "1908", "b": "1911", "c": "1919", "d": "1935"}'::jsonb as hi) h) where id = 'cf35c070-9ba3-4cc4-894a-c0cbea45ebff' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'ब्रह्म समाज के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। राममोहन राय ने 1828 में कलकत्ता में ब्रह्म समाज की स्थापना की, जो मूर्ति-पूजा के विरोध वाले, उपनिषदों पर आधारित एकेश्वरवादी विचारों पर टिका था, और वे उस अभियान में प्रमुख थे जिसके बाद बेंटिक ने 1829 के विनियम द्वारा सती प्रथा समाप्त की।', updated_at = now(), question_data = question_data || '{"statements_hi": ["ब्रह्म समाज की स्थापना राजा राममोहन राय ने 1828 में कलकत्ता में की।", "इसने मूर्ति-पूजा का विरोध किया और उपनिषदों के दर्शन के आधार पर एकेश्वरवाद का समर्थन किया।", "गवर्नर-जनरल लॉर्ड विलियम बेंटिक के समय बंगाल सती विनियम, 1829 द्वारा सती प्रथा के उन्मूलन में राजा राममोहन राय की प्रमुख भूमिका थी।"]}'::jsonb where id = 'a9756c4a-1cdb-401c-afe6-f5b1dd16be2a' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'स्वतंत्रता संग्राम के क्रांतिकारी आंदोलनों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। कथन 1 उत्पत्ति गलत बताता है: अनुशीलन समिति बंगाल में शुरू हुई और कलकत्ता तथा युगांतर गुटों में बँटी। कथन 2 हमले का श्रेय गलत व्यक्ति को देता है: 1930 का चटगाँव शस्त्रागार हमला सूर्य सेन के नेतृत्व में हुआ, चंद्रशेखर आज़ाद के नहीं। कथन 3 वास्तविक क्रम को उलट देता है: संगठन 1924 में हिंदुस्तान रिपब्लिकन एसोसिएशन के रूप में बना और 1928 में ही इसका नाम हिंदुस्तान सोशलिस्ट रिपब्लिकन एसोसिएशन रखा गया।', updated_at = now(), question_data = question_data || '{"statements_hi": ["अनुशीलन समिति की उत्पत्ति पंजाब में हुई, और युगांतर समूह लाहौर में स्थित एक अलग हुआ गुट था।", "चटगाँव शस्त्रागार हमले (1930) का नेतृत्व चंद्रशेखर आज़ाद ने किया था, और इसका उद्देश्य बंगाल के सरकारी शस्त्रागारों पर कब्ज़ा करना था।", "संगठन की स्थापना 1924 में मूल रूप से हिंदुस्तान सोशलिस्ट रिपब्लिकन एसोसिएशन (HSRA) के नाम से हुई, और 1928 में भगत सिंह के शामिल होने के बाद ही इसका नाम बदलकर हिंदुस्तान रिपब्लिकन एसोसिएशन (HRA) किया गया।"]}'::jsonb where id = '37acdc76-26a0-4276-bbf1-932267a2bec8' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'अंतरिम सरकार (1946) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। कथन 1 पदाधिकारी बदल देता है: अंतरिम सरकार (सितंबर 1946) की कार्यकारी परिषद के उपाध्यक्ष वल्लभभाई पटेल नहीं, जवाहरलाल नेहरू थे। कथन 2 गलत है: मुस्लिम लीग ने पहले शामिल होने से इनकार किया, अक्टूबर 1946 में ही शामिल हुई, और अड़ंगा डालने वाला रुख अपनाया। कथन 3 विभाग बदल देता है: लियाकत अली ख़ान के पास वित्त विभाग था, जबकि गृह विभाग पटेल के पास था।', updated_at = now(), question_data = question_data || '{"statements_hi": ["अंतरिम सरकार सितंबर 1946 में बनी, जिसमें सरदार वल्लभभाई पटेल कार्यकारी परिषद के उपाध्यक्ष थे।", "मुस्लिम लीग सितंबर 1946 में अंतरिम सरकार के गठन के समय से ही उसमें शामिल थी और शुरू से कांग्रेस के नेतृत्व वाले प्रशासन के साथ पूरा सहयोग करती रही।", "लीग के शामिल होने के बाद अंतरिम सरकार में मुस्लिम लीग के लियाकत अली ख़ान के पास गृह विभाग था।"]}'::jsonb where id = '3ed3dc8b-50ae-418f-a7d3-9da57ba445d8' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'शिमला सम्मेलन (1945) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं: वेवेल ने सवर्ण हिंदुओं और मुसलमानों के समान प्रतिनिधित्व वाली पुनर्गठित कार्यकारी परिषद के प्रस्ताव के लिए सम्मेलन बुलाया, और यह मुख्य रूप से जिन्ना की इस ज़िद के कारण टूटा कि सभी मुस्लिम सदस्यों को नामित करने का अधिकार केवल लीग को है। कथन 2 गलत है: सम्मेलन में सहमति नहीं बनी और यह बिना किसी हल के समाप्त हुआ, परिषद की सहमत संरचना के साथ नहीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["1945 का शिमला सम्मेलन वायसराय लॉर्ड वेवेल ने सवर्ण हिंदुओं और मुसलमानों के समान प्रतिनिधित्व वाली एक नई कार्यकारी परिषद के प्रस्ताव पर चर्चा के लिए बुलाया।", "सम्मेलन सफल रहा, और नई कार्यकारी परिषद की संरचना पर सहमति बन गई।", "सम्मेलन मुख्य रूप से जिन्ना की इस ज़िद के कारण विफल हुआ कि परिषद के सभी मुस्लिम सदस्यों को नामित करने का अधिकार केवल मुस्लिम लीग को है।"]}'::jsonb where id = '37a578e3-0c24-4b22-80a0-868ba1199dcf' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = '1942 की ''अगस्त क्रांति'' किस आंदोलन का दूसरा नाम है?', explanation_hi = '''अगस्त क्रांति'' भारत छोड़ो आंदोलन को कहते हैं, जो AICC के बंबई प्रस्ताव और गांधीजी के ''करो या मरो'' के आह्वान के बाद अगस्त 1942 में शुरू हुआ। असहयोग आंदोलन (1920-22) और सविनय अवज्ञा आंदोलन (1930-34) संघर्ष के पहले के चरण हैं, और व्यक्तिगत सत्याग्रह (1940) भारत छोड़ो से पहले का एक अधिक सीमित, सांकेतिक अभियान था।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "असहयोग आंदोलन", "b": "सविनय अवज्ञा आंदोलन", "c": "भारत छोड़ो आंदोलन", "d": "व्यक्तिगत सत्याग्रह"}'::jsonb as hi) h) where id = '8adcaad3-f812-4a99-b53e-7d29cfe188dd' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'नाट्य, नृत्य और संगीत पर प्राचीन भारत का आधारभूत ग्रंथ ''नाट्यशास्त्र'' किस ऋषि की रचना माना जाता है?', explanation_hi = 'नाट्यशास्त्र भरत मुनि की रचना माना जाता है और यह भारतीय नाट्य, नृत्य और संगीत का आधारभूत ग्रंथ है, जिसके रस (सौंदर्यात्मक भाव) संबंधी सिद्धांत आज भी संदर्भित होते हैं। वाल्मीकि रामायण से, पतंजलि योगसूत्र (और संस्कृत व्याकरण पर एक भाष्य) से, और पाणिनि संस्कृत व्याकरण ग्रंथ अष्टाध्यायी से जुड़े हैं; इनमें से किसी ने नाट्यशास्त्र नहीं लिखा।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "वाल्मीकि", "b": "भरत मुनि", "c": "पतंजलि", "d": "पाणिनि"}'::jsonb as hi) h) where id = '654331fc-b689-40fb-853c-d33efc07cc2e' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'सम्राट अकबर के ''नवरत्नों'' में गिने जाने वाले तानसेन का हिंदुस्तानी शास्त्रीय संगीत की किस विधा से सबसे गहरा संबंध है?', explanation_hi = 'तानसेन का सबसे गहरा संबंध हिंदुस्तानी शास्त्रीय गायन की गंभीर, संयमित विधा ध्रुपद से है, और परंपरा उन्हें मियाँ की मल्हार और मियाँ की तोड़ी सहित कई रागों की रचना का श्रेय देती है। ख़याल बाद में एक अलग विधा के रूप में विकसित हुआ; ठुमरी एक हल्की, उप-शास्त्रीय विधा है; और क़व्वाली एक सूफ़ी भक्ति संगीत परंपरा है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "ध्रुपद", "b": "ख़याल", "c": "ठुमरी", "d": "क़व्वाली"}'::jsonb as hi) h) where id = '4e2fc452-e01e-481a-a6d8-9b266c4f2918' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'हिंदुस्तानी गायन संगीत के इतिहास के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: ग्वालियर के राजा मानसिंह तोमर ध्रुपद के बड़े संरक्षक थे। कथन 2 कालदोष (anachronism) है: ख़याल एक मध्यकालीन विधा है और प्राचीन ग्रंथ नाट्यशास्त्र में इसका वर्णन नहीं है। कथन 3 शासक बदल देता है: सदारंग 18वीं सदी में मुहम्मद शाह ''रंगीला'' के दरबार से जुड़े हैं, औरंगज़ेब से नहीं, जिसे दरबारी संगीत को हतोत्साहित करने के लिए याद किया जाता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["15वीं-16वीं शताब्दी में ग्वालियर के राजा मानसिंह तोमर से ध्रुपद को भारी राजकीय संरक्षण मिला।", "भरत के नाट्यशास्त्र में ख़याल का गायन की एक प्रमुख विधा के रूप में विस्तार से वर्णन है।", "औरंगज़ेब के दरबारी संगीतज्ञ सदारंग (नियामत ख़ान) को ख़याल को उसका परिष्कृत शास्त्रीय रूप देने का श्रेय दिया जाता है।"]}'::jsonb where id = 'b7d11c8a-11bb-4bde-b4b9-4716ab65c113' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'अजंता की गुफाओं के भित्ति-चित्र मुख्य रूप से किसके दृश्य दर्शाते हैं?', explanation_hi = 'अजंता की गुफाओं के भित्ति-चित्र मुख्य रूप से बौद्ध विषयों पर हैं, जिनमें जातक कथाएँ (बुद्ध के पूर्व जन्मों की कहानियाँ) और बुद्ध के जीवन के प्रसंग हैं। रामायण/महाभारत के चित्रण, मुगल दरबार के दृश्य और शिव/विष्णु की पौराणिक कथाएँ बिल्कुल अलग कलात्मक और धार्मिक परंपराओं की हैं, जिनका अजंता के बौद्ध प्रतिमा-कार्यक्रम से संबंध नहीं।', updated_at = now() where id = 'ee38ee90-2f3a-41f8-97c1-601e572d781e' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'पहाड़ी और राजपूत चित्रकला शैलियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है। कथन 2 संरक्षक बदल देता है: कांगड़ा शैली कांगड़ा के राजा संसार चंद के संरक्षण में फली-फूली, जबकि सावंत सिंह (नागरीदास) ने किशनगढ़ शैली को संरक्षण दिया। कथन 3 शैली बदल देता है: ''बनी ठनी'' किशनगढ़ का प्रसिद्ध चित्र है, जिसे चित्रकार निहाल चंद का माना जाता है, बूँदी की कृति नहीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["बसोहली को पहाड़ी चित्रकला शैलियों में सबसे पुरानी माना जाता है, जो चटख रंगों और मज़बूत रेखाओं के लिए जानी जाती है।", "पहाड़ी चित्रकला की कांगड़ा शैली किशनगढ़ के राजा सावंत सिंह के संरक्षण में फली-फूली।", "''बनी ठनी'' चित्र राजस्थान की बूँदी शैली से जुड़ा है।"]}'::jsonb where id = '2166154c-c866-4e36-bd2b-4f1720cc0e2d' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित में से किस जलवायु प्रकार में तापमान का वार्षिक अंतर सबसे अधिक होता है?', explanation_hi = 'साइबेरिया और उत्तरी कनाडा की उप-आर्कटिक महाद्वीपीय जलवायु, जो बड़े भू-भागों के भीतर गहराई में है, पृथ्वी पर सबसे अधिक वार्षिक अंतर वाली है: वर्खोयान्स्क में जनवरी का औसत -45 डिग्री सेल्सियस से नीचे और जुलाई का लगभग +15 डिग्री रहता है, यानी 60 डिग्री से अधिक का अंतर। भूमध्यरेखीय जलवायु में वार्षिक अंतर सबसे कम (2-3 डिग्री) है, और बाकी दोनों अक्षांश या समुद्र के कारण संतुलित रहती हैं।', updated_at = now() where id = '4415dc51-5698-44cd-8e86-652d80d3395e' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'स्थानीय पवनों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1, 2 और 4 सही हैं। चिनूक फ़ॉन प्रकार की पवन है: रॉकी पर्वत के प्रतिपवन (पूर्वी) ढलान से उतरते समय हवा गर्म होती है और बर्फ़ को तेज़ी से पिघलाती है, इसीलिए इसे ''हिम-भक्षी'' कहते हैं। मिस्ट्रल रोन घाटी से होकर गल्फ़ ऑफ़ लायन तक बहती है, और सिरोको सहारा की गर्म, धूल भरी हवा भूमध्यसागर के पार ले जाती है। कथन 3 गलत है: हरमट्टन सहारा से पश्चिम अफ़्रीका पर बहने वाली शुष्क, धूल भरी उत्तर-पूर्वी पवन है; आर्द्र तट पर इसकी शुष्कता इतनी राहत देती है कि इसे ''डॉक्टर'' कहते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["चिनूक रॉकी पर्वत के पूर्वी ढलानों से नीचे बहने वाली गर्म, शुष्क पवन है।", "मिस्ट्रल रोन घाटी से भूमध्यसागर की ओर बहने वाली ठंडी पवन है।", "हरमट्टन अटलांटिक से पश्चिम अफ़्रीका के तट पर बहने वाली गर्म, आर्द्र पवन है।", "सिरोको सहारा से दक्षिणी यूरोप की ओर बहने वाली गर्म पवन है।"]}'::jsonb where id = '898362eb-8729-4493-bbb8-75443b7375f1' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'पश्चिमी और पूर्वी घाट के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन I और III सही हैं। पश्चिमी घाट पश्चिमी तट के साथ लगभग बिना टूटे चलते हैं और केवल थाल, भोर और पाल घाट जैसे दर्रों से पार किए जा सकते हैं, जबकि पूर्वी घाट महानदी, गोदावरी, कृष्णा और कावेरी से कटे होने के कारण असतत हैं। केरल की अन्नामलाई पहाड़ियों में अनामुडी (2,695 मी) प्रायद्वीपीय भारत की सबसे ऊँची चोटी है। कथन II उलटा है: पश्चिमी घाट (औसतन लगभग 900-1,600 मी) पूर्वी घाट (लगभग 600 मी) से ऊँचे हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["पश्चिमी घाट पूर्वी घाट की तुलना में अधिक सतत (लगातार) हैं।", "पश्चिमी घाट की ऊँचाई आम तौर पर पूर्वी घाट से कम है।", "प्रायद्वीपीय भारत की सबसे ऊँची चोटी अनामुडी पश्चिमी घाट में है।"]}'::jsonb where id = '7badca29-9d03-443a-89d3-55dcca8fdf0c' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'प्रायद्वीपीय भारत की नदियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं। नर्मदा और तापी प्रायद्वीप की दो बड़ी पश्चिम-वाहिनी नदियाँ हैं; ये भ्रंश घाटियों (rift valleys) से होकर बहती हैं और डेल्टा नहीं, ज्वारनदमुख (estuary) बनाती हैं। महानदी छत्तीसगढ़ में सिहावा के पास से निकलती है और ओडिशा तट पर डेल्टा बनाती है। कथन 3 गलत है: गोदावरी (लगभग 1,465 किमी) सचमुच सबसे लंबी प्रायद्वीपीय नदी है, पर दूसरी पूर्व-वाहिनी नदियों की तरह यह बंगाल की खाड़ी पर एक बड़ा डेल्टा बनाती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["नर्मदा और तापी भ्रंश घाटियों से होकर पश्चिम की ओर बहती हैं।", "महानदी छत्तीसगढ़ से निकलती है और ओडिशा में डेल्टा बनाती है।", "प्रायद्वीपीय भारत की सबसे लंबी नदी गोदावरी डेल्टा के बजाय ज्वारनदमुख (estuary) पर समाप्त होती है।"]}'::jsonb where id = 'fe6f1f35-be37-449b-a8ad-318f743c7fc7' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित देशों पर विचार कीजिए:', explanation_hi = 'केवल दो, अज़रबैजान और ईरान। कैस्पियन सागर की सीमा पाँच देशों से लगती है: रूस, कज़ाख़स्तान, तुर्कमेनिस्तान, ईरान और अज़रबैजान। जॉर्जिया काकेशस के दूसरी ओर काला सागर के तट पर है। उज़्बेकिस्तान विश्व के उन दो देशों में है जो दोहरे भूमिबद्ध (doubly landlocked) हैं; कज़ाख़स्तान के साथ उसका साझा जलाशय अरल सागर है, कैस्पियन नहीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["अज़रबैजान", "जॉर्जिया", "ईरान", "उज़्बेकिस्तान"], "closing_hi": "उपर्युक्त में से कितने देशों की तटरेखा कैस्पियन सागर पर है?"}'::jsonb where id = '10d10abe-f260-4441-8762-a42a0f42dd41' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
